export default async function ({ parentId, path }, ctx) {
  if (typeof parentId !== "string" || !parentId.trim() || typeof path !== "string")
    throw Error("Set a parent and path");
  const parts = path.split("/");
  if (!parts.length || parts.some((x) => !x.trim())) throw Error("Path segments must be non-empty");
  let parent = parentId;
  for (const name of parts) {
    const quote = (x) => x.replace(/\\/g, "\\\\").replace(/'/g, "\\'");
    const q = `'${quote(parent)}' in parents and trashed = false and mimeType = 'application/vnd.google-apps.folder' and name = '${quote(name)}'`;
    let token,
      seen = new Set(),
      matches = [];
    do {
      const r = await ctx.actions.call("googledrive.files.list", {
        q,
        pageSize: 100,
        ...(token ? { pageToken: token } : {}),
      });
      if (!Array.isArray(r?.files)) throw Error("Invalid Drive list");
      matches.push(...r.files);
      token = r.nextPageToken;
      if (token) {
        if (typeof token !== "string" || seen.has(token)) throw Error("Invalid page cursor");
        seen.add(token);
      }
    } while (token);
    if (matches.length > 1) throw Error("Ambiguous duplicate folder " + name);
    if (matches.length) {
      if (typeof matches[0].id !== "string" || !matches[0].id || matches[0].name !== name)
        throw Error("Invalid Drive match");
      parent = matches[0].id;
    } else {
      const created = await ctx.actions.call("googledrive.files.create", {
        name,
        mimeType: "application/vnd.google-apps.folder",
        parents: [parent],
      });
      if (typeof created?.id !== "string" || !created.id)
        throw Error("Folder creation not confirmed");
      parent = created.id;
    }
  }
  return { folderId: parent };
}
